struct Item {
    int id;
    std::string name;
    double price;
};

// --- In-Memory Database (Replace with a real database for production) ---
class InMemoryDatabase {
public:
    void addItem(const Item& item) {
        items[item.id] = item;
    }

    Item getItem(int id) {
        auto it = items.find(id);
        if (it != items.end()) {
            return it->second;
        } else {
            // Item not found - return a default or throw an exception
            return {}; // Return empty item to indicate not found
        }
    }

    void updateItem(int id, const Item& new_item) {
       if (items.find(id) != items.end()) {
           items[id] = new_item;
       } else {
          // Could throw an exception here if you want stricter error handling
          std::cout << "Item with ID " << id << " not found for update." << std::endl;
       }
    }

    void deleteItem(int id) {
        items.erase(id);
    }

private:
    std::map<int, Item> items;
};


// --- Simple HTTP Request Handler (Very Basic - No Frameworks) ---
class RestHandler {
public:
    RestHandler(InMemoryDatabase& db) : db_(db) {}

    // GET /items  - Returns all items.
    std::string handleGetItems() {
        std::stringstream ss;
        ss << "[";
        for (auto const& [id, item] : db_.items) {
            ss << "{id:" << id << ", name:" << item.name << ", price:" << item.price << "}";
            if (id < db_.items.size() - 1) {
                ss << ",";
            }
        }
        ss << "]";
        return ss.str();
    }

    // GET /items/{id} - Returns an item by ID.
    std::string handleGetItem(int id) {
        Item item = db_.getItem(id);
        if (item.id == 0) { // Check if the item was found or not
            return "{\n  \"error\": \"Item not found\"\n}";
        }

        std::stringstream ss;
        ss << "{";
        ss << "\"id:" << item.id << "\", ";
        ss << "\"name:" << item.name << "\", ";
        ss << "\"price:" << item.price << "}";
        ss << "";
        return ss.str();

    }


    // POST /items - Creates a new item.
    std::string handlePostItem(const std::string& request_body) {
        std::stringstream ss(request_body);
        Item newItem;
        ss >> newItem.id >> newItem.name >> newItem.price;

        if (newItem.id == 0 || newItem.name == "" || newItem.price <= 0) { // Handle invalid input
            return "{\n  \"error\": \"Invalid item data\"\n}";
        }

        db_.addItem(newItem);
        return "{\n  \"message\": \"Item created successfully\",\n  \"id:" << newItem.id << "\"\n}";
    }


     // PUT /items/{id} - Updates an existing item by ID
    std::string handlePutItem(int id, const std::string& request_body) {
        std::stringstream ss(request_body);
        Item updatedItem;
        ss >> updatedItem.id >> updatedItem.name >> updatedItem.price;

        if (updatedItem.id == 0 || updatedItem.name == "" || updatedItem.price <= 0) {
            return "{\n  \"error\": \"Invalid item data\"\n}";
        }

        Item existingItem = db_.getItem(id);
        if (existingItem.id == 0){ // Item doesn't exist, handle error as needed.
            return "{\n  \"error\": \"Item not found\"\n}";
        }


        updatedItem.id = id; // Ensure the ID is correct for updating
        db_.updateItem(id, updatedItem);

        return "{\n  \"message\": \"Item updated successfully\",\n  \"id:" << id << "\"\n}";
    }



     // DELETE /items/{id} - Deletes an item by ID.
    std::string handleDeleteItem(int id) {
        db_.deleteItem(id);
        return "{\n  \"message\": \"Item deleted successfully\",\n  \"id:" << id << "\"\n}";
    }


private:
    InMemoryDatabase& db_;
};



// --- Example Usage (Main Function) ---
int main() {
    InMemoryDatabase database;

    RestHandler handler(database);

    std::cout << "GET /items: " << handler.handleGetItems() << std::endl;

    // Create a new item
    std::cout << "\nPOST /items (data: id=1 name=Laptop price=1200): " << handler.handlePostItem("1 1 1200") << std::endl;
    std::cout << "GET /items: " << handler.handleGetItems() << std::endl;

     // Get a specific item by ID
    std::cout << "\nGET /items/1: " << handler.handleGetItem(1) << std::endl;


    //Update an item
    std::cout << "\nPUT /items/1 (data: id=1 name=New Laptop price=1500): " << handler.handlePutItem(1, "1 1 New Laptop 1500") << std::endl;
     std::cout << "GET /items: " << handler.handleGetItems() << std::endl;

    // Delete an item
    std::cout << "\nDELETE /items/1: " << handler.handleDeleteItem(1) << std::endl;
    std::cout << "GET /items: " << handler.handleGetItems() << std::endl;

    return 0;
}
```

