  wordToCode["apple"] = "NAME_1_APPLE";
  wordToCode["banana"] = "NAME_1_BANANA";
  wordToCode["orange"] = "NAME_1_ORANGE";
  wordToCode["grape"] = "NAME_1_GRAPE";
