  wordToCode["water"] = "NAME_1_WATER";
  wordToCode["sun"] = "NAME_1_SUN";
  wordToCode["moon"] = "NAME_1_MOON";
  wordToCode["star"] = "NAME_1_STAR";


  string inputText;

  cout << "Enter English text to convert: ";
  getline(cin, inputText); // Use getline to handle spaces in the input.

  // Convert the text to lowercase for case-insensitive matching
  transform(inputText.begin(), inputText.end(), inputText.begin(), ::tolower);

  string outputCode = "";
  string words[100]; // Assuming max 100 words - adjust if needed
  int wordCount = 0;

  // Tokenize the input text (split into individual words)
  size_t pos = 0;
  while ((pos = inputText.find(" ")) != string::npos) {
    words[wordCount] = inputText.substr(0, pos);
    inputText.erase(0, pos + 1);
    wordCount++;
  }

  // Add the last word if any remains
  if (!inputText.empty()) {
      words[wordCount] = inputText;
  }


  for (int i = 0; i < wordCount; ++i) {
    string word = words[i];
    if (wordToCode.count(word)) {
      outputCode += wordToCode[word] + ", ";
    } else {
      cout << "Warning: Word '" << word << "' not found in the mapping." << endl; // Handle unknown words
    }
  }

  // Remove the trailing ", " and add a newline if necessary
  if (!outputCode.empty()) {
    outputCode = outputCode.substr(0, outputCode.length() - 2);
  }


  cout << "NAME_1 code: " << outputCode << endl;

  return 0;
}
```

