```typescript
function parsePath(path: string): any[] {
  if (!path) {
    return [];
  }

  const result: any[] = [];
  let current = path;

  while (current) {
    if (current === "[") {
      result.push(null);
      current = ""; // Consume the opening bracket
    } else if (current === "]") {
      current = ""; // Consume the closing bracket
    } else if (current === ".") {
      result.push(null);
      current = ""; // Consume dot
    } else if (isNaN(parseInt(current, 10))) {
      result.push(current);
      current = "";
    } else {
      const num = parseInt(current, 10);
      result.push(num);
      current = "";
    }
  }

  return result;
}


// Test cases (using Jest)
describe('parsePath', () => {
  it("should return an empty array for an empty string", () => {
    expect(parsePath("")).toEqual([]);
  });

  it("should parse a simple path", () => {
    expect(parsePath("hello")).toEqual(["hello"]);
  });

  it("should parse a path with an index", () => {
    expect(parsePath("hello[1]")).toEqual(["hello", 1]);
  });

  it("should parse a path with multiple indices", () => {
    expect(parsePath("hello[]")).toEqual(["hello", null]);
    expect(parsePath("hello[1][2][3]")).toEqual(["hello", 1, 2, 3]);
    expect(parsePath("hello[world][foo][bar]")).toEqual(["hello", "world", "foo", "bar"]);
    expect(parsePath("hello[world][3][foo][2][bar]")).toEqual([
      "hello",
      "world",
      3,
      "foo",
      2,
      "bar",
    ]);
  });

  it("should parse a path with dots", () => {
    expect(parsePath("hello.foo")).toEqual(["hello", "foo"]);
    expect(parsePath("hello.foo.bar")).toEqual(["hello", "foo", "bar"]);
  });

  it("should handle paths with empty indices", () => {
     expect(parsePath("hello[].foo")).toEqual(["hello", null, "foo"]);
  })
});
```

